import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { useEffect } from "react";
import { filterDogsByTemperament, getTemperaments } from "../redux/actions";

export default function Filter2() {
  const temperaments = useSelector(state => state.temperaments);

  const dispatch = useDispatch();

 
  
  const temperamentsOrder = temperaments.sort((a, b) => { //se ordena alfabeticamente para que salga bien en el select
    if (a.name > b.name) { return 1; }
    if (a.name < b.name) { return -1;}
    return 0;
  })

  useEffect(() => {
    dispatch(getTemperaments());
  }, [dispatch]);

  const handleSelect = e => {
    e.preventDefault();

    dispatch(filterDogsByTemperament(e.target.value));
  };

  return (
    <div>
      <select
        className={styles.selectInput}
        defaultValue="default"
        onChange={handleSelect}
      >
        <option value="default">Elija un temperamento</option>
        {temperaments?.map(t => (
          <option value={t.name} key={t.id}>
            {t.name}
          </option>
        ))}
      </select>
    </div>
  );
}
